    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address proposed, string memory typeStr) public {
        uint before = c.proposalCount(); if (__ESBMC_reverted()) return;
        c.newAddressProposal(proposed, typeStr); if (__ESBMC_reverted()) return;
