// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address proposed, string memory typeStr) internal {
        uint256 before;
        try c.proposalCount() returns (uint256 __r) { before = __r; } catch { return; }
        try c.newAddressProposal(proposed, typeStr) {} catch { return; }
        uint256 newID;
        try c.proposalCount() returns (uint256 __r) { newID = __r; } catch { return; }
        assertTrue(newID == before + 1 && c.mapPID_address(newID) == proposed);
    }

    function testFuzz_run(address proposed, string memory typeStr) public {
        vm.assume(proposed.code.length == 0 && uint160(proposed) > 0xffff && proposed != address(this) && proposed != address(c) && proposed != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && proposed != 0x000000000000000000636F6e736F6c652e6c6f67 && proposed != 0x4e59b44847b379578588920cA78FbF26c0B4956C && proposed != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(proposed, typeStr);
    }

    receive() external payable {}
}
